package com.aistock.prediction.analysis;
import com.aistock.common.*;import com.aistock.prediction.modelcatalog.ModelRecords.Actor;import com.fasterxml.jackson.databind.ObjectMapper;import jakarta.servlet.http.HttpServletRequest;import org.springframework.security.core.Authentication;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*;
@RestController public class AnalysisController {
 private final AnalysisService service;private final ObjectMapper m;public AnalysisController(AnalysisService service,ObjectMapper m){this.service=service;this.m=m;}
 @PostMapping("/api/v1/stock-analyses")public ApiResponse<?> generate(Authentication auth,HttpServletRequest req){var user=user(auth);AnalysisInput input;try{var bytes=req.getInputStream().readNBytes(2049);if(bytes.length>2048)throw invalid();var n=m.readTree(bytes);if(n==null||!n.isObject()||n.size()<5||n.size()>6||!Set.of("operationId","instrumentId","from","to","marketVersionId","predictionId").containsAll(iterableNames(n)))throw invalid();for(String k:List.of("operationId","instrumentId","from","to","marketVersionId"))if(!n.path(k).isTextual())throw invalid();input=new AnalysisInput(uuid(n.path("operationId").asText()),n.path("instrumentId").asText(),LocalDate.parse(n.path("from").asText()),LocalDate.parse(n.path("to").asText()),uuid(n.path("marketVersionId").asText()),n.path("predictionId").isMissingNode()||n.path("predictionId").isNull()?null:uuidText(n.path("predictionId")));}catch(java.io.IOException|IllegalArgumentException|java.time.format.DateTimeParseException e){throw invalid();}return ok(service.generate(user,input),req);}
 @GetMapping("/api/v1/stock-analyses")public ApiResponse<?> list(Authentication auth,@RequestParam String instrumentId,@RequestParam String from,@RequestParam String to,@RequestParam(defaultValue="1")int page,HttpServletRequest req){LocalDate f,t;try{f=LocalDate.parse(from);t=LocalDate.parse(to);}catch(java.time.format.DateTimeParseException e){throw invalid();}return ok(service.list(user(auth),instrumentId,f,t,page),req);}
 @GetMapping("/api/v1/stock-analyses/prediction-options")public ApiResponse<?> options(Authentication auth,@RequestParam String instrumentId,@RequestParam(defaultValue="1")int page,HttpServletRequest req){return ok(service.options(user(auth),instrumentId,page),req);}
 @GetMapping("/api/v1/stock-analyses/{id}")public ApiResponse<?> get(Authentication auth,@PathVariable UUID id,HttpServletRequest req){return ok(service.get(user(auth),id),req);}
 private ApiResponse<?> ok(Object data,HttpServletRequest r){return ApiResponse.success(data,TraceIds.normalize(r.getHeader("X-Trace-Id")));}
 private UUID user(Authentication a){if(a==null||!a.isAuthenticated()||!(a.getPrincipal() instanceof Actor actor))throw new BusinessException("AUTH_REQUIRED","请先登录",HttpStatus.UNAUTHORIZED);return actor.userId();}
 private Set<String> iterableNames(com.fasterxml.jackson.databind.JsonNode n){var names=new HashSet<String>();n.fieldNames().forEachRemaining(names::add);return names;}
 private UUID uuidText(com.fasterxml.jackson.databind.JsonNode n){if(!n.isTextual())throw invalid();return uuid(n.asText());}
 private UUID uuid(String s){if(!s.matches("[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}"))throw invalid();return UUID.fromString(s);}
 private BusinessException invalid(){return new BusinessException("AI_REQUEST_INVALID","分析请求格式不正确",HttpStatus.BAD_REQUEST);}
}